-- GATE PACK 0266 policies (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select tablename as obj, policyname, cmd, permissive, array_to_string(roles, ',') as roles
from pg_catalog.pg_policies
where schemaname = 'public' and tablename in ('studio_legal_name_access', 'client_legal_name_access_audit', 'client_legal_identities')
order by 1, 2;
